insert into household (id, name, currency_code, ai_context_text) values
  ('83f5b53b-ff04-4c97-983b-fac5bcda2db2', 'Rivera Household', 'USD', 'Two-parent US household with one teenager, discretionary spending only (fixed costs are handled outside this budget). The grid tracks each person''s monthly allowance per category as whole amounts; a negotiation redistributes allowance between people and always nets to zero, leaving the category and household totals unchanged. Available savings and progress toward a $5,000 goal (target February 1, 2027) are entered by a member at setup and shown as a single number, separate from this grid. September starts at baseline allowances with no negotiations yet, so the propose-and-agree flow can be demonstrated from a clean slate.');
